(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const q=new URLSearchParams(location.search), fmt=v=>v?new Date(v).toLocaleString():'—', day=v=>v?new Date(v+'T00:00:00').toLocaleDateString():'—';
function replaceQuery(values={}){const u=new URL(location.href);u.search='';for(const [k,v] of Object.entries(values)){if(v!==undefined&&v!==null&&v!=='')u.searchParams.set(k,String(v))}history.replaceState({},'',u.pathname+u.search+u.hash);[...q.keys()].forEach(k=>q.delete(k));u.searchParams.forEach((v,k)=>q.set(k,v));}
const money=(v,c='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency:String(c||'USD').toUpperCase()}).format(Number(v||0));
let SB=null;function db(){if(SB)return SB;for(const k of ['supabaseClient','s4uSupabase','S4USupabase','sb','supabaseDb','supabaseApp']){const x=window[k];if(x?.from&&x?.auth){SB=x;return x}}for(const k of Object.keys(window)){try{const x=window[k];if(x&&typeof x==='object'&&x.from&&x.auth?.getSession){SB=x;return x}}catch{}}throw new Error('Supabase client is not available.');}
const setTitle=(a,b='')=>{if($('#tmTitle'))$('#tmTitle').textContent=a;if($('#tmSubtitle'))$('#tmSubtitle').textContent=b};
function unlock(){document.documentElement.classList.remove('s4u-auth-pending');const l=$('#s4u-auth-loading');if(l)l.style.display='none'}
function msg(t,type='ok'){const e=$('#tmMessage');if(!e)return;e.hidden=false;e.className='tm-message'+(type==='error'?' error':type==='warn'?' warn':'');e.textContent=t;scrollTo({top:0,behavior:'smooth'});if(type==='ok')setTimeout(()=>e.hidden=true,4500)}
function badge(v){const s=String(v||'').toLowerCase(),c=/active|approved|accepted|complete|completed|published|issued|delivered|ready/.test(s)?'good':/declined|cancel|failed|revoked|inactive|unavailable/.test(s)?'bad':/pending|draft|review|sent|scheduled|processing|limited|new|manual/.test(s)?'warn':'';return `<span class="tm-badge ${c}">${esc(v||'—')}</span>`}
function table(h,rows){return `<div class="tm-table-wrap"><table class="tm-table"><thead><tr>${h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${h.length}"><div class="tm-empty">No records found.</div></td></tr>`}</tbody></table></div>`}
const metrics=a=>`<div class="tm-grid">${a.map(([x,y])=>`<div class="tm-metric"><small>${esc(x)}</small><strong>${esc(y)}</strong></div>`).join('')}</div>`;
const opt=(v,l,s='')=>`<option value="${esc(v)}"${String(v)===String(s)?' selected':''}>${esc(l)}</option>`;
const formObj=f=>Object.fromEntries(new FormData(f).entries());
async function rows(t,order='created_at',asc=false){let z=await db().from(t).select('*').order(order,{ascending:asc});if(z.error)throw z.error;return z.data||[]}
async function one(t,id){let z=await db().from(t).select('*').eq('id',id).maybeSingle();if(z.error)throw z.error;return z.data}
async function rpc(name,args={}){let z=await db().rpc(name,args);if(z.error)throw z.error;return z.data}
async function legacy(module,extra={}){let z=await db().functions.invoke('enterprise-testing-command',{body:{action:'module',module,...extra}});if(z.error)throw z.error;if(z.data?.error)throw new Error(z.data.error);return z.data?.data||z.data}
async function legacyAct(operation,payload={}){let z=await db().functions.invoke('enterprise-testing-command',{body:{action:'action',operation,payload}});if(z.error)throw z.error;if(z.data?.error)throw new Error(z.data.error);return z.data?.result||z.data}
const testingService=s=>{const m=s.metadata||{};return m.finance_business_code==='testing'||m.testing_operation===true||m.seller_surface==='screenings4u_testing'||m.catalog_id};
const NAV=[
 ['Operations',[['admin-testing.html','Overview'],['admin-testing-operations.html','Testing Operations'],['admin-work-management.html','Work Orders'],['admin-testing-results.html','Results'],['admin-testing-result-documents.html','Result Documents']]],
 ['Service Requests',[['admin-testing-mobile.html','Mobile Testing'],['admin-testing-post-accident.html','Post-Accident Testing'],['admin-testing-background-checks.html','Background Checks'],['admin-testing-proposals.html','Proposals']]],
 ['Network & Accounts',[['admin-testing-collector-network.html','Collector Network'],['admin-testing-providers.html','Providers'],['admin-testing-employers.html','Employers & Customers'],['admin-testing-portal-access.html','Portal Access']]],
 ['Content & Records',[['admin-testing-catalog.html','Testing Catalog'],['admin-testing-documents.html','Documents'],['admin-testing-reports.html','Reports'],['admin-testing-blog.html','Blog Editor']]]
];
function installNav(){const root=$('#admin-lms-sidebar-target'),here=location.pathname.split('/').pop()||'admin-testing.html';if(!root)return;const patch=()=>{const s=root.querySelector('.ep-side-scroll');if(!s)return false;s.innerHTML=NAV.map(([g,links])=>`<details class="ep-side-group"${links.some(x=>x[0]===here)?' open':''}><summary><span>${g}</span><i>›</i></summary><div class="ep-side-section">${links.map(([h,l])=>`<a class="ep-side-link ${h===here?'active':''}" href="${h}"><span class="ep-side-icon">•</span><span>${l}</span></a>`).join('')}</div></details>`).join('');return true};if(!patch()){const mo=new MutationObserver(()=>{if(patch())mo.disconnect()});mo.observe(root,{childList:true,subtree:true});setTimeout(()=>{patch();mo.disconnect()},2500)}}
function links(){return `<div class="tm-section-links">${NAV.flatMap(x=>x[1]).filter(x=>x[0]!=='admin-testing.html').map(([h,l])=>`<a class="tm-link-card" href="${h}"><strong>${esc(l)}</strong><span>Open management page</span></a>`).join('')}</div>`}
async function home(){setTitle('Testing Management','screenings4u operational management. Financial reporting remains in Finance.');const [w,r,c,b,col,p,d]=await Promise.all([rows('testing_work_orders'),rows('testing_employer_service_requests'),rows('testing_cases'),rows('testing_background_checks'),rows('collector_network_submissions'),rows('testing_proposals'),rows('testing_document_deliveries')]);const active=c.filter(x=>!['released','completed','cancelled'].includes(x.status));$('#tmRoot').innerHTML=metrics([['Open Work Orders',w.filter(x=>!['completed','cancelled'].includes(x.status)).length],['Active Testing Cases',active.length],['Service Requests',r.filter(x=>!['completed','cancelled'].includes(x.status)).length],['Pending Background Checks',b.filter(x=>!['complete','cancelled'].includes(x.status)).length]])+`<div class="tm-card"><div class="tm-card-head"><div><h2>Management Areas</h2><p>Every workflow opens as a full management page.</p></div></div><div class="tm-card-body">${links()}</div></div>`+metrics([['Approved Collectors',col.filter(x=>x.status==='approved').length],['Open Proposals',p.filter(x=>!['accepted','declined','expired'].includes(x.status)).length],['Portal Deliveries',d.filter(x=>x.portal_status==='sent').length],['Result-Ready Cases',c.filter(x=>x.status==='result_ready').length]]);}

async function collectors(){setTitle('Collector Network','Manage collector applications from collector_network_submissions and maintain assignment readiness.');const id=q.get('id');if(id||q.get('new'))return collectorEdit(id);const a=await rows('collector_network_submissions');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn primary" href="admin-testing-collector-network.html?new=1">+ Add Collector</a></div><div class="tm-toolbar two"><div class="tm-field"><label>Search</label><input id="s" placeholder="Name, company, city, state, ZIP, service area"></div><div class="tm-field"><label>Status</label><select id="st"><option value="">All statuses</option>${['new','reviewing','contacted','approved','declined'].map(x=>opt(x,x)).join('')}</select></div></div><div id="collectorList"></div>`;const draw=()=>{const term=$('#s').value.toLowerCase(),st=$('#st').value;let f=a.filter(x=>(!st||x.status===st)&&(!term||[x.full_name,x.email,x.company_name,x.city,x.state,x.zip_code,x.service_areas,x.certifications].join(' ').toLowerCase().includes(term)));$('#collectorList').innerHTML=table(['Collector','Location','Service Area','Status','Availability','Management'],f.map(x=>`<tr><td><strong>${esc(x.full_name)}</strong><span class="tm-sub">${esc(x.company_name||'')} · ${esc(x.email)}</span></td><td>${esc([x.city,x.state,x.zip_code].filter(Boolean).join(', ')||'—')}</td><td>${esc((x.service_areas||'—').slice(0,120))}</td><td>${badge(x.status)}</td><td>${badge(x.availability_status)}</td><td><a class="tm-btn small primary" href="admin-testing-collector-network.html?id=${x.id}">View / Edit</a></td></tr>`))};$('#s').oninput=draw;$('#st').onchange=draw;draw()}
async function collectorEdit(id){const c=id?await one('collector_network_submissions',id):{};setTitle(id?'Manage Collector':'Add Collector','View, edit, approve, decline, and maintain collector availability.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-collector-network.html">← Collector Network</a></div><div class="tm-card"><div class="tm-card-head"><div><h2>${id?esc(c.full_name):'New Collector'}</h2>${id?`<p>Submitted ${fmt(c.created_at)}</p>`:''}</div>${id?badge(c.status):''}</div><div class="tm-card-body"><form id="f" class="tm-form-grid"><div class="tm-field"><label>Full Name *</label><input name="full_name" required value="${esc(c.full_name||'')}"></div><div class="tm-field"><label>Email *</label><input name="email" type="email" required value="${esc(c.email||'')}"></div><div class="tm-field"><label>Phone</label><input name="phone" value="${esc(c.phone||'')}"></div><div class="tm-field"><label>Company</label><input name="company_name" value="${esc(c.company_name||'')}"></div><div class="tm-field"><label>Website</label><input name="website" value="${esc(c.website||'')}"></div><div class="tm-field"><label>ZIP</label><input name="zip_code" value="${esc(c.zip_code||'')}"></div><div class="tm-field"><label>City</label><input name="city" value="${esc(c.city||'')}"></div><div class="tm-field"><label>State</label><input name="state" value="${esc(c.state||'')}"></div><div class="tm-field full"><label>Service Areas</label><textarea name="service_areas">${esc(c.service_areas||'')}</textarea></div><div class="tm-field full"><label>Collector Type / Availability Submitted</label><textarea name="collector_type">${esc(c.collector_type||'')}</textarea></div><div class="tm-field full"><label>Certifications</label><textarea name="certifications">${esc(c.certifications||'')}</textarea></div><div class="tm-field"><label>Years Experience</label><input name="years_experience" value="${esc(c.years_experience||'')}"></div><div class="tm-field"><label>Status</label><select name="status">${['new','reviewing','contacted','approved','declined'].map(x=>opt(x,x,c.status||'new')).join('')}</select></div><div class="tm-field"><label>Availability</label><select name="availability_status">${['available','limited','unavailable','inactive'].map(x=>opt(x,x,c.availability_status||'available')).join('')}</select></div><div class="tm-field full"><label>Application Message / Services</label><textarea name="message">${esc(c.message||'')}</textarea></div><div class="tm-field full"><label>Internal Notes</label><textarea name="internal_notes">${esc(c.internal_notes||'')}</textarea></div><div class="tm-actions full"><button class="tm-btn primary" type="submit">Save Collector</button>${id?`<a class="tm-btn" href="admin-work-management.html?new=1&collector_id=${id}">Create Work Order</a><a class="tm-btn danger" href="admin-testing-collector-network.html?id=${id}&delete=1">Delete Collector</a>`:''}</div></form></div></div>${id&&q.get('delete')?`<div class="tm-danger-zone"><strong>Delete collector record?</strong><p>This action is blocked if the collector is referenced by a work order assignment.</p><form id="deleteForm"><button class="tm-btn danger" type="submit">Confirm Delete</button> <a class="tm-btn" href="admin-testing-collector-network.html?id=${id}">Cancel</a></form></div>`:''}`;$('#f').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget);p.updated_at=new Date().toISOString();let z=id?await db().from('collector_network_submissions').update(p).eq('id',id).select().single():await db().from('collector_network_submissions').insert(p).select().single();if(z.error)throw z.error;msg('Collector saved.');replaceQuery({id:z.data.id});await collectors()}catch(x){msg(x.message,'error')}};if($('#deleteForm'))$('#deleteForm').onsubmit=async e=>{e.preventDefault();try{const z=await db().from('collector_network_submissions').delete().eq('id',id);if(z.error)throw z.error;replaceQuery();await collectors()}catch(x){msg(x.message,'error')}}}

async function workOrders(){const id=q.get('id');if(id||q.get('new'))return workOrderEdit(id);setTitle('Work Orders','Create, assign, send, track, and complete Mobile, On-Site Workplace, and Post-Accident work orders.');const [a,cols]=await Promise.all([rows('testing_work_orders'),rows('collector_network_submissions')]);const cm=new Map(cols.map(x=>[x.id,x]));$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn primary" href="admin-work-management.html?new=1">+ Create Work Order</a></div><div class="tm-toolbar two"><div class="tm-field"><label>Search</label><input id="s" placeholder="Work order, company, location, status"></div><div class="tm-field"><label>Type</label><select id="ty"><option value="">All types</option>${[['mobile_testing','Mobile Testing'],['onsite_workplace_testing','On-Site Workplace'],['post_accident','Post Accident']].map(x=>opt(...x)).join('')}</select></div></div><div id="list"></div>`;const draw=()=>{const term=$('#s').value.toLowerCase(),ty=$('#ty').value;let f=a.filter(x=>(!ty||x.work_order_type===ty)&&(!term||[x.work_order_number,x.company_name,x.city,x.state,x.status,x.work_order_type].join(' ').toLowerCase().includes(term)));$('#list').innerHTML=table(['Work Order','Type','Location','Collector','Services / Donors','Total','Status','Management'],f.map(x=>`<tr><td><strong>${esc(x.work_order_number)}</strong><span class="tm-sub">${fmt(x.created_at)}</span></td><td>${esc(x.work_order_type.replaceAll('_',' '))}</td><td>${esc([x.site_name,x.city,x.state].filter(Boolean).join(' · '))}</td><td>${esc(cm.get(x.assigned_collector_id)?.full_name||'Unassigned')}</td><td>${esc(x.donor_count||1)} donor(s)</td><td>${money(x.total,x.currency)}</td><td>${badge(x.status)}</td><td><a class="tm-btn small primary" href="admin-work-management.html?id=${x.id}">Manage</a></td></tr>`))};$('#s').oninput=draw;$('#ty').onchange=draw;draw()}
async function workOrderEdit(id){const [wo,services,cols]=await Promise.all([id?one('testing_work_orders',id):Promise.resolve({}),rows('services','name',true),rows('collector_network_submissions')]);const items=id?(await db().from('testing_work_order_services').select('*').eq('work_order_id',id).order('sort_order')).data||[]:[];const assignments=id?(await db().from('testing_work_order_assignments').select('*').eq('work_order_id',id).order('created_at',{ascending:false})).data||[]:[];const events=id?(await db().from('testing_work_order_events').select('*').eq('work_order_id',id).order('created_at',{ascending:false})).data||[]:[];const approved=cols.filter(x=>x.status==='approved'&&!['unavailable','inactive'].includes(x.availability_status));setTitle(id?`Work Order ${wo.work_order_number}`:'Create Work Order','Location, service scope, terms, pricing, collector assignment, and response tracking.');let sourceReq=q.get('request_id');if(sourceReq&&!id){const r=await one('testing_employer_service_requests',sourceReq);Object.assign(wo,{source_request_id:r.id,work_order_type:r.request_type==='post_accident'?'post_accident':r.request_type==='onsite_testing'?'onsite_workplace_testing':'mobile_testing',company_name:'',site_name:r.site_name,address_line_1:r.address_line_1,city:r.city,state:r.state,postal_code:r.postal_code,contact_name:r.primary_contact,contact_email:r.contact_email,contact_phone:r.contact_phone||r.request_contact_phone,donor_count:r.employee_count||1,requested_date:r.preferred_date,requested_start_time:r.preferred_time,testing_purpose:r.testing_purpose,special_instructions:r.special_instructions})}
 const serviceRows=(items.length?items:[{service_name:'',quantity:1,unit_price:0,line_total:0}]).map((x,i)=>serviceRow(x,i)).join('');
 $('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-work-management.html">← Work Orders</a>${id?`<a class="tm-btn" href="admin-work-management.html?id=${id}&assign=1">Assign Collector</a>`:''}</div><div class="tm-card"><div class="tm-card-head"><div><h2>Work Order Details</h2><p>Post Accident, Mobile Testing, and On-Site Workplace Testing are supported.</p></div>${id?badge(wo.status):''}</div><div class="tm-card-body"><form id="woForm" class="tm-form-grid"><input type="hidden" name="source_request_id" value="${esc(wo.source_request_id||'')}"><div class="tm-field"><label>Work Order Type *</label><select name="work_order_type">${[['mobile_testing','Mobile Testing'],['onsite_workplace_testing','On-Site Workplace Testing'],['post_accident','Post Accident Testing']].map(x=>opt(x[0],x[1],wo.work_order_type||q.get('type')||'mobile_testing')).join('')}</select></div><div class="tm-field"><label>Status</label><select name="status">${['draft','ready_to_assign','sent','accepted','reassignment_required','scheduled','in_progress','completed','cancelled'].map(x=>opt(x,x,wo.status||'draft')).join('')}</select></div><div class="tm-field"><label>Company</label><input name="company_name" value="${esc(wo.company_name||'')}"></div><div class="tm-field"><label>Site Name</label><input name="site_name" value="${esc(wo.site_name||'')}"></div><div class="tm-field"><label>Contact Name</label><input name="contact_name" value="${esc(wo.contact_name||'')}"></div><div class="tm-field"><label>Contact Email</label><input name="contact_email" type="email" value="${esc(wo.contact_email||'')}"></div><div class="tm-field"><label>Contact Phone</label><input name="contact_phone" value="${esc(wo.contact_phone||'')}"></div><div class="tm-field"><label>Donor Count</label><input name="donor_count" type="number" min="1" value="${esc(wo.donor_count||1)}"></div><div class="tm-field full"><label>Street Address *</label><input name="address_line_1" required value="${esc(wo.address_line_1||'')}"></div><div class="tm-field"><label>City *</label><input name="city" required value="${esc(wo.city||'')}"></div><div class="tm-field"><label>State *</label><input name="state" required value="${esc(wo.state||'')}"></div><div class="tm-field"><label>ZIP</label><input name="postal_code" value="${esc(wo.postal_code||'')}"></div><div class="tm-field"><label>Requested Date</label><input name="requested_date" type="date" value="${esc(wo.requested_date||'')}"></div><div class="tm-field"><label>Start Time</label><input name="requested_start_time" type="time" value="${esc(wo.requested_start_time||'')}"></div><div class="tm-field"><label>End Time</label><input name="requested_end_time" type="time" value="${esc(wo.requested_end_time||'')}"></div><div class="tm-field full"><label>Testing Purpose</label><input name="testing_purpose" value="${esc(wo.testing_purpose||'')}"></div><div class="tm-field full"><label>Special Instructions</label><textarea name="special_instructions">${esc(wo.special_instructions||'')}</textarea></div><div class="tm-field full"><label>Terms & Conditions</label><textarea name="terms_and_conditions">${esc(wo.terms_and_conditions||'')}</textarea></div><div class="full"><h3>Services & Pricing</h3><div id="serviceRows">${serviceRows}</div><button class="tm-btn" id="addService" type="button">+ Add Service Line</button></div><div class="tm-field"><label>Subtotal</label><input name="subtotal" type="number" step="0.01" value="${esc(wo.subtotal||0)}"></div><div class="tm-field"><label>Travel Fee</label><input name="travel_fee" type="number" step="0.01" value="${esc(wo.travel_fee||0)}"></div><div class="tm-field"><label>Other Fees</label><input name="other_fees" type="number" step="0.01" value="${esc(wo.other_fees||0)}"></div><div class="tm-field"><label>Total</label><input name="total" type="number" step="0.01" value="${esc(wo.total||0)}"></div><div class="tm-actions full"><button class="tm-btn primary" type="submit">Save Work Order</button>${id?`<a class="tm-btn" href="admin-work-management.html?id=${id}&assign=1">Search / Assign Collector</a>`:''}</div></form></div></div>${id&&q.get('assign')?assignPanel(approved,wo):''}${id?`<div class="tm-two"><div class="tm-card"><div class="tm-card-head"><h2>Assignment History</h2></div><div class="tm-card-body">${assignments.map(a=>`<div class="tm-list-item"><strong>${badge(a.status)} ${esc(cols.find(c=>c.id===a.collector_id)?.full_name||'Collector')}</strong><p>Sent ${fmt(a.sent_at)} · Responded ${fmt(a.responded_at)}</p>${a.decline_reason?`<p>${esc(a.decline_reason)}</p>`:''}</div>`).join('')||'<div class="tm-empty">No assignments yet.</div>'}</div></div><div class="tm-card"><div class="tm-card-head"><h2>Work Order Log</h2></div><div class="tm-card-body">${events.map(e=>`<div class="tm-list-item"><strong>${esc(e.event_type.replaceAll('_',' '))}</strong><p>${fmt(e.created_at)}</p>${e.notes?`<p>${esc(e.notes)}</p>`:''}</div>`).join('')||'<div class="tm-empty">No events yet.</div>'}</div></div></div>`:''}`;
 function bindRemove(){$$('[data-remove-service]').forEach(b=>b.onclick=()=>b.closest('.tm-service-row').remove())}bindRemove();$('#addService').onclick=()=>{const d=document.createElement('div');d.innerHTML=serviceRow({service_name:'',quantity:1,unit_price:0},Date.now());$('#serviceRows').append(d.firstElementChild);bindRemove()};
 $('#woForm').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget),svc=$$('.tm-service-row').map(r=>{const q=n=>r.querySelector(`[name=${n}]`).value;return {service_name:q('service_name'),service_description:q('service_description'),quantity:Number(q('quantity')||1),unit_price:Number(q('unit_price')||0),line_total:Number(q('quantity')||1)*Number(q('unit_price')||0)}}).filter(x=>x.service_name);p.donor_count=Number(p.donor_count||1);for(const k of ['subtotal','travel_fee','other_fees','total'])p[k]=Number(p[k]||0);let z=id?await db().from('testing_work_orders').update({...p,updated_at:new Date().toISOString()}).eq('id',id).select().single():await db().from('testing_work_orders').insert(p).select().single();if(z.error)throw z.error;await db().from('testing_work_order_services').delete().eq('work_order_id',z.data.id);if(svc.length){let si=await db().from('testing_work_order_services').insert(svc.map((x,i)=>({...x,work_order_id:z.data.id,sort_order:i})));if(si.error)throw si.error}await db().from('testing_work_order_events').insert({work_order_id:z.data.id,event_type:id?'work_order_updated':'work_order_created',actor_type:'staff'});msg('Work order saved.');replaceQuery({id:z.data.id});await workOrders()}catch(x){msg(x.message,'error')}};
 if($('#assignForm'))$('#assignForm').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget),z=await rpc('testing_assign_work_order',{p_work_order_id:id,p_collector_id:p.collector_id,p_offered_amount:p.offered_amount?Number(p.offered_amount):null,p_acceptance_deadline:p.acceptance_deadline?new Date(p.acceptance_deadline).toISOString():null});msg('Work order sent to collector for approval or denial.');await workOrders()}catch(x){msg(x.message,'error')}};
}
function serviceRow(x,i){return `<div class="tm-service-row"><div class="tm-field"><label>Service *</label><input name="service_name" value="${esc(x.service_name||'')}"><input name="service_description" placeholder="Description" value="${esc(x.service_description||'')}"></div><div class="tm-field"><label>Quantity</label><input name="quantity" type="number" step="0.01" min="0.01" value="${esc(x.quantity||1)}"></div><div class="tm-field"><label>Unit Price</label><input name="unit_price" type="number" step="0.01" min="0" value="${esc(x.unit_price||0)}"></div><button class="tm-btn danger small" type="button" data-remove-service>Remove</button></div>`}
function assignPanel(cols,wo){const term=[wo.city,wo.state,wo.postal_code].filter(Boolean).join(', ');return `<div class="tm-card"><div class="tm-card-head"><div><h2>Assign Collector</h2><p>Approved collectors only. Use service area, state, ZIP, certification, and availability to select the right collector.</p></div></div><div class="tm-card-body"><div class="tm-rich-note">Work order location: <strong>${esc(term)}</strong></div><form id="assignForm" class="tm-form-grid" style="margin-top:14px"><div class="tm-field full"><label>Collector</label><select name="collector_id" required><option value="">Choose collector</option>${cols.map(c=>opt(c.id,`${c.full_name} — ${[c.city,c.state,c.zip_code].filter(Boolean).join(', ')} — ${c.availability_status}`)).join('')}</select></div><div class="tm-field"><label>Collector Compensation</label><input name="offered_amount" type="number" step="0.01" min="0"></div><div class="tm-field"><label>Response Deadline</label><input name="acceptance_deadline" type="datetime-local"></div><div class="full"><button class="tm-btn primary" type="submit">Send Work Order to Collector</button></div></form><div class="tm-divider"></div>${cols.length?table(['Collector','Location','Service Areas','Certifications','Availability'],cols.map(c=>`<tr><td>${esc(c.full_name)}<span class="tm-sub">${esc(c.company_name||'')}</span></td><td>${esc([c.city,c.state,c.zip_code].filter(Boolean).join(', '))}</td><td>${esc((c.service_areas||'').slice(0,160))}</td><td>${esc((c.certifications||'').slice(0,140))}</td><td>${badge(c.availability_status)}</td></tr>`)):'<div class="tm-empty">No approved, available collectors found.</div>'}</div></div>`}

async function requestPage(kind){const isPost=kind==='post_accident',title=isPost?'Post-Accident Testing Requests':'Mobile Testing Requests';setTitle(title,`Requests received from screenings4u.com. Create a work order from any request.`);const [reqs,emps]=await Promise.all([rows('testing_employer_service_requests'),rows('testing_employers','employer_name',true)]),em=new Map(emps.map(x=>[x.id,x]));let f=reqs.filter(r=>isPost?r.request_type==='post_accident':['onsite_testing','mobile_testing'].includes(r.request_type));$('#tmRoot').innerHTML=metrics([['Requests',f.length],['New / Submitted',f.filter(x=>['draft','submitted'].includes(x.status)).length],['In Review',f.filter(x=>x.status==='reviewing').length],['Scheduled / Completed',f.filter(x=>['scheduled','completed'].includes(x.status)).length]])+table(['Request','Employer','Location','Contact','Employees','Status','Work Order'],f.map(r=>`<tr><td><strong>${esc(r.request_number)}</strong><span class="tm-sub">${fmt(r.created_at)}</span></td><td>${esc(em.get(r.employer_id)?.employer_name||'—')}</td><td>${esc([r.site_name,r.city,r.state,r.postal_code].filter(Boolean).join(' · '))}</td><td>${esc(r.primary_contact||r.requested_by_name||'—')}<span class="tm-sub">${esc(r.contact_email||r.request_contact_phone||'')}</span></td><td>${esc(r.employee_count||1)}</td><td>${badge(r.status)}</td><td><a class="tm-btn primary small" href="admin-work-management.html?new=1&request_id=${r.id}&type=${isPost?'post_accident':'mobile_testing'}">Create Work Order</a></td></tr>`))}

async function operations(){setTitle('Testing Operations','Manage purchased drug and alcohol tests, manually build donor passes, and push them to the customer portal.');const caseId=q.get('case_id');if(caseId||q.get('new_pass'))return operationDetail(caseId);const [cases,passes]=await Promise.all([rows('testing_cases'),rows('testing_donor_passes')]);const pm=new Map(passes.map(x=>[x.testing_case_id,x]));$('#tmRoot').innerHTML=metrics([['Testing Cases',cases.length],['Awaiting Schedule',cases.filter(x=>x.status==='awaiting_schedule').length],['Ready for Collection',cases.filter(x=>x.status==='ready_for_collection').length],['Donor Passes',passes.length]])+table(['Case','Customer / Donor','Test','Status','Donor Pass','Management'],cases.map(c=>`<tr><td><strong>${esc(c.case_number)}</strong></td><td>${esc(c.company_name||c.customer_name||'—')}<span class="tm-sub">${esc(c.donor_name||c.customer_email||'')}</span></td><td>${esc(c.test_type||c.panel_name||'Testing')}<span class="tm-sub">${esc(c.specimen_type||'')}</span></td><td>${badge(c.status)}</td><td>${pm.get(c.id)?`${badge(pm.get(c.id).status)} ${esc(pm.get(c.id).pass_number)}`:'Not created'}</td><td><a class="tm-btn primary small" href="admin-testing-operations.html?case_id=${c.id}">Manage / Donor Pass</a></td></tr>`))}
async function operationDetail(id){const [c,passes]=await Promise.all([one('testing_cases',id),db().from('testing_donor_passes').select('*').eq('testing_case_id',id).order('created_at',{ascending:false})]);const p=passes.data?.[0]||{};setTitle(`Operations — ${c.case_number}`,'Manual test ordering and screenings4u-branded Donor Pass management.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-operations.html">← Operations</a></div><div class="tm-two"><div class="tm-card"><div class="tm-card-head"><h2>Testing Case</h2>${badge(c.status)}</div><div class="tm-card-body"><div class="tm-kv">${[['Case',c.case_number],['Customer',c.customer_name],['Company',c.company_name],['Donor',c.donor_name],['Email',c.donor_email||c.customer_email],['Test reason',c.test_reason],['Test type',c.test_type],['Specimen',c.specimen_type],['Panel',c.panel_name],['DOT',c.dot_test?'Yes':'No'],['DOT Agency',c.dot_agency]].map(([k,v])=>`<div>${esc(k)}</div><div>${esc(v||'—')}</div>`).join('')}</div></div></div><div class="tm-card"><div class="tm-card-head"><h2>Donor Pass Preview</h2></div><div class="tm-card-body"><img class="tm-logo-email" src="https://elpbnytpciqnbexiaebp.supabase.co/storage/v1/object/public/enterprise_branding/logo-screenings4u.png" alt="screenings4u"><h3>${esc(p.pass_number||'New Donor Pass')}</h3><p><strong>${esc(p.donor_name||c.donor_name||'Donor')}</strong></p><p>${esc(p.test_type||c.test_type||'Testing')} · ${esc(p.panel_name||c.panel_name||'')}</p><p>${esc(p.collection_site_name||'Collection site to be entered')}</p><p>${p.collection_deadline?`Deadline: ${fmt(p.collection_deadline)}`:''}</p></div></div></div><div class="tm-card"><div class="tm-card-head"><div><h2>${p.id?'Manage Donor Pass':'Create Donor Pass'}</h2><p>One-page branded donor pass.</p></div>${p.id?badge(p.status):''}</div><div class="tm-card-body"><form id="passForm" class="tm-form-grid"><div class="tm-field"><label>Donor Name *</label><input name="donor_name" required value="${esc(p.donor_name||c.donor_name||'')}"></div><div class="tm-field"><label>Donor Email</label><input name="donor_email" type="email" value="${esc(p.donor_email||c.donor_email||c.customer_email||'')}"></div><div class="tm-field"><label>Donor Phone</label><input name="donor_phone" value="${esc(p.donor_phone||c.donor_phone||'')}"></div><div class="tm-field"><label>Company</label><input name="company_name" value="${esc(p.company_name||c.company_name||'')}"></div><div class="tm-field"><label>Test Reason</label><input name="test_reason" value="${esc(p.test_reason||c.test_reason||'')}"></div><div class="tm-field"><label>Test Type</label><input name="test_type" value="${esc(p.test_type||c.test_type||'')}"></div><div class="tm-field"><label>Specimen</label><input name="specimen_type" value="${esc(p.specimen_type||c.specimen_type||'')}"></div><div class="tm-field"><label>Panel</label><input name="panel_name" value="${esc(p.panel_name||c.panel_name||'')}"></div><div class="tm-field"><label>Collection Site</label><input name="collection_site_name" value="${esc(p.collection_site_name||'')}"></div><div class="tm-field"><label>Collection Deadline</label><input name="collection_deadline" type="datetime-local" value="${p.collection_deadline?new Date(p.collection_deadline).toISOString().slice(0,16):''}"></div><div class="tm-field full"><label>Collection Site Address</label><input name="collection_site_address" value="${esc(p.collection_site_address||'')}"></div><div class="tm-field"><label>Confirmation Code</label><input name="confirmation_code" value="${esc(p.confirmation_code||'')}"></div><div class="tm-field"><label>Status</label><select name="status">${['draft','issued','void'].map(x=>opt(x,x,p.status||'draft')).join('')}</select></div><div class="tm-field full"><label>Instructions</label><textarea name="instructions">${esc(p.instructions||'Bring a government-issued photo ID and this donor pass to the collection location. Follow all collection-site instructions.')}</textarea></div><div class="tm-actions full"><button class="tm-btn primary" type="submit">Save Donor Pass</button>${p.id&&p.status!=='issued'?`<a class="tm-btn" href="admin-testing-operations.html?case_id=${id}&issue=${p.id}">Push to Portal + Notify</a>`:''}</div></form></div></div>${p.id&&q.get('issue')?`<div class="tm-card"><div class="tm-card-head"><h2>Issue Donor Pass</h2></div><div class="tm-card-body"><p>This sends the pass to the customer's portal when a portal account is linked and queues a branded screenings4u email notification.</p><form id="issueForm"><button class="tm-btn primary" type="submit">Confirm Issue & Notify</button> <a class="tm-btn" href="admin-testing-operations.html?case_id=${id}">Cancel</a></form></div></div>`:''}`;$('#passForm').onsubmit=async e=>{e.preventDefault();try{const x=formObj(e.currentTarget),row={...x,testing_case_id:c.id,order_id:c.order_id||null,employer_id:c.employer_id||null,customer_user_id:c.customer_user_id||null,dot_test:!!c.dot_test,dot_agency:c.dot_agency||null,updated_at:new Date().toISOString()};if(x.collection_deadline)row.collection_deadline=new Date(x.collection_deadline).toISOString();else row.collection_deadline=null;let z=p.id?await db().from('testing_donor_passes').update(row).eq('id',p.id).select().single():await db().from('testing_donor_passes').insert(row).select().single();if(z.error)throw z.error;msg('Donor pass saved.');replaceQuery({case_id:id});await operations()}catch(x){msg(x.message,'error')}};if($('#issueForm'))$('#issueForm').onsubmit=async e=>{e.preventDefault();try{await rpc('testing_issue_donor_pass',{p_id:p.id});msg('Donor pass issued and notifications queued.');replaceQuery({case_id:id});await operations()}catch(x){msg(x.message,'error')}}}

async function results(){const id=q.get('case_id');if(id)return resultEdit(id);setTitle('Testing Results','Build results, upload official documents, release results, and maintain the admin log.');const [cases,docs]=await Promise.all([rows('testing_cases'),rows('testing_case_documents')]);const dc={};docs.forEach(d=>(dc[d.testing_case_id]??=[]).push(d));const f=cases.filter(c=>c.overall_result||['lab_received','lab_processing','mro_review','result_ready','released','completed'].includes(c.status));$('#tmRoot').innerHTML=table(['Case','Donor','Test','Result','MRO','Documents','Status','Management'],f.map(c=>`<tr><td>${esc(c.case_number)}</td><td>${esc(c.donor_name||'—')}</td><td>${esc(c.test_type||c.panel_name||'—')}</td><td>${badge(c.overall_result||'Pending')}</td><td>${c.mro_required?(c.mro_verified_at?'Verified':'Required'):'Not required'}</td><td>${(dc[c.id]||[]).length}</td><td>${badge(c.status)}</td><td><a class="tm-btn primary small" href="admin-testing-results.html?case_id=${c.id}">Manage Result</a></td></tr>`))}
async function resultEdit(id){const [c,docs,ev]=await Promise.all([one('testing_cases',id),db().from('testing_case_documents').select('*').eq('testing_case_id',id).order('created_at',{ascending:false}),db().from('testing_case_events').select('*').eq('testing_case_id',id).order('created_at',{ascending:false})]);setTitle(`Result — ${c.case_number}`,'Build result details, attach official MRO/lab documents, and release them to the customer portal.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-results.html">← Results</a></div><div class="tm-card"><div class="tm-card-head"><h2>Result Record</h2>${badge(c.status)}</div><div class="tm-card-body"><form id="resultForm" class="tm-form-grid"><div class="tm-field"><label>Overall Result</label><input name="overall_result" value="${esc(c.overall_result||'')}"></div><div class="tm-field"><label>Status</label><select name="status">${['lab_received','lab_processing','mro_review','result_ready','released','completed'].map(x=>opt(x,x,c.status)).join('')}</select></div><div class="tm-field"><label>Lab Accession Number</label><input name="lab_accession_number" value="${esc(c.lab_accession_number||'')}"></div><div class="tm-field"><label>MRO Required</label><select name="mro_required">${opt('false','No',String(!!c.mro_required))+opt('true','Yes',String(!!c.mro_required))}</select></div><div class="tm-field full"><label>Internal / Result Notes</label><textarea name="notes">${esc(c.notes||'')}</textarea></div><div class="full"><button class="tm-btn primary" type="submit">Save Result</button></div></form></div></div><div class="tm-two"><div class="tm-card"><div class="tm-card-head"><div><h2>Official Result Document</h2><p>Upload official MRO/lab document. It remains private until released.</p></div></div><div class="tm-card-body"><form id="docForm" class="tm-form-grid"><div class="tm-field"><label>Document Title</label><input name="title" value="Official Result — ${esc(c.case_number)}" required></div><div class="tm-field"><label>File</label><input id="resultFile" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" required></div><div class="full"><button class="tm-btn primary" type="submit">Upload Official Result</button></div></form><div class="tm-divider"></div>${(docs.data||[]).map(d=>`<div class="tm-list-item"><strong>${esc(d.title)} ${d.document_type==='official_result'?'<span class="tm-pill">Official Result</span>':''}</strong><p>${fmt(d.created_at)} · ${badge(d.visibility)}</p><div class="tm-actions"><button class="tm-btn small" data-open-doc="${d.id}">View</button>${d.visibility==='internal'?`<a class="tm-btn primary small" href="admin-testing-results.html?case_id=${id}&deliver=${d.id}">Release to Customer</a>`:''}</div></div>`).join('')||'<div class="tm-empty">No documents uploaded.</div>'}</div></div><div class="tm-card"><div class="tm-card-head"><h2>Detailed Admin Log</h2></div><div class="tm-card-body">${(ev.data||[]).map(e=>`<div class="tm-list-item"><strong>${esc(e.event_type)}</strong><p>${fmt(e.created_at)} · ${esc(e.from_status||'')} → ${esc(e.to_status||'')}</p>${e.notes?`<p>${esc(e.notes)}</p>`:''}</div>`).join('')||'<div class="tm-empty">No events.</div>'}</div></div></div>${q.get('deliver')?`<div class="tm-card"><div class="tm-card-head"><h2>Release Official Result</h2></div><div class="tm-card-body"><p>This makes the document available in customers.screenings4u.com and queues a branded screenings4u email notification.</p><form id="deliverForm"><button class="tm-btn primary" type="submit">Confirm Release</button> <a class="tm-btn" href="admin-testing-results.html?case_id=${id}">Cancel</a></form></div></div>`:''}`;$('#resultForm').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget);p.mro_required=p.mro_required==='true';if(p.status==='result_ready'&&!c.result_ready_at)p.result_ready_at=new Date().toISOString();let z=await db().from('testing_cases').update(p).eq('id',id);if(z.error)throw z.error;await db().from('testing_case_events').insert({testing_case_id:id,event_type:'result_updated',from_status:c.status,to_status:p.status,notes:p.notes||null});msg('Result record saved.');setTimeout(()=>{init().catch(x=>msg(x.message,'error'))},350)}catch(x){msg(x.message,'error')}};$('#docForm').onsubmit=async e=>{e.preventDefault();try{const f=$('#resultFile').files[0],name=f.name.replace(/[^a-zA-Z0-9._-]/g,'_'),docId=crypto.randomUUID(),path=`cases/${id}/${docId}/${name}`;let up=await db().storage.from('testing-documents').upload(path,f,{contentType:f.type,upsert:false});if(up.error)throw up.error;let ins=await db().from('testing_case_documents').insert({id:docId,testing_case_id:id,document_type:'official_result',title:formObj(e.currentTarget).title,storage_bucket:'testing-documents',storage_path:path,mime_type:f.type,file_size:f.size,visibility:'internal',metadata:{official_result:true}});if(ins.error)throw ins.error;await db().from('testing_case_events').insert({testing_case_id:id,event_type:'official_result_document_uploaded',notes:name});msg('Official result document uploaded.');setTimeout(()=>{init().catch(x=>msg(x.message,'error'))},400)}catch(x){msg(x.message,'error')}};$$('[data-open-doc]').forEach(b=>b.onclick=async()=>{try{const d=await one('testing_case_documents',b.dataset.openDoc),z=await db().storage.from(d.storage_bucket).createSignedUrl(d.storage_path,300);if(z.error)throw z.error;window.open(z.data.signedUrl,'_blank','noopener')}catch(x){msg(x.message,'error')}});if($('#deliverForm'))$('#deliverForm').onsubmit=async e=>{e.preventDefault();try{await rpc('testing_deliver_result_document',{p_document_id:q.get('deliver')});msg('Result released to portal and branded notifications queued.');replaceQuery({case_id:id});await resultEdit(id)}catch(x){msg(x.message,'error')}}}

async function resultDocuments(){setTitle('Result Documents','All official MRO/lab result documents released or prepared for customers and employers.');const [docs,cases,del]=await Promise.all([rows('testing_case_documents'),rows('testing_cases'),rows('testing_document_deliveries')]);const cm=new Map(cases.map(x=>[x.id,x]));const dm={};del.filter(x=>x.source_type==='testing_case_document').forEach(x=>(dm[x.source_id]??=[]).push(x));const f=docs.filter(x=>x.document_type==='official_result'||x.metadata?.official_result);$('#tmRoot').innerHTML=table(['Document','Case / Donor','Visibility','Portal / Email Delivery','Uploaded','View'],f.map(d=>{const c=cm.get(d.testing_case_id),ds=dm[d.id]||[];return `<tr><td><strong>${esc(d.title)}</strong><span class="tm-sub">${esc(d.mime_type||'')}</span></td><td>${esc(c?.case_number||'—')}<span class="tm-sub">${esc(c?.donor_name||'')}</span></td><td>${badge(d.visibility)}</td><td>${ds.length?ds.map(x=>`${badge(x.portal_status)} ${badge(x.email_status)}`).join(' '):'Not delivered'}</td><td>${fmt(d.created_at)}</td><td><a class="tm-btn small" href="admin-testing-results.html?case_id=${d.testing_case_id}">Open Result</a></td></tr>`}) )}

async function documents(){const id=q.get('id');if(id)return documentDetail(id);setTitle('Private Documents','Upload and securely store private documents, then optionally send them to a customer or employer.');const [d,profiles,emps]=await Promise.all([rows('testing_private_documents'),rows('user_profiles'),rows('testing_employers','employer_name',true)]);$('#tmRoot').innerHTML=`<div class="tm-card"><div class="tm-card-head"><div><h2>Upload Private Document</h2><p>Stored in a private Supabase bucket.</p></div></div><div class="tm-card-body"><form id="uploadForm" class="tm-form-grid"><div class="tm-field"><label>Title *</label><input name="title" required></div><div class="tm-field"><label>Category</label><input name="category" value="general"></div><div class="tm-field full"><label>Description</label><textarea name="description"></textarea></div><div class="tm-field"><label>Customer (optional)</label><select name="customer_user_id"><option value="">None</option>${profiles.filter(x=>x.email).map(x=>opt(x.id,`${x.display_name||[x.first_name,x.last_name].filter(Boolean).join(' ')||'Customer'} — ${x.email}`)).join('')}</select></div><div class="tm-field"><label>Employer (optional)</label><select name="employer_id"><option value="">None</option>${emps.map(x=>opt(x.id,x.employer_name)).join('')}</select></div><div class="tm-field full"><label>File *</label><input id="privateFile" type="file" required></div><div class="full"><button class="tm-btn primary" type="submit">Upload Document</button></div></form></div></div>${table(['Document','Category','Customer / Employer','Uploaded','Management'],d.map(x=>`<tr><td><strong>${esc(x.title)}</strong><span class="tm-sub">${esc(x.original_filename||'')}</span></td><td>${esc(x.category)}</td><td>${esc(profiles.find(p=>p.id===x.customer_user_id)?.email||emps.find(e=>e.id===x.employer_id)?.employer_name||'Private / internal')}</td><td>${fmt(x.created_at)}</td><td><a class="tm-btn small primary" href="admin-testing-documents.html?id=${x.id}">View / Send</a></td></tr>`))}`;$('#uploadForm').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget),f=$('#privateFile').files[0],id=crypto.randomUUID(),name=f.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`private/${new Date().getFullYear()}/${id}/${name}`;let up=await db().storage.from('testing-private-documents').upload(path,f,{contentType:f.type});if(up.error)throw up.error;let z=await db().from('testing_private_documents').insert({id,title:p.title,description:p.description||null,category:p.category||'general',storage_path:path,original_filename:name,mime_type:f.type,file_size:f.size,customer_user_id:p.customer_user_id||null,employer_id:p.employer_id||null,metadata:{}}).select().single();if(z.error)throw z.error;msg('Private document uploaded.');replaceQuery({id});await documents()}catch(x){msg(x.message,'error')}}}
async function documentDetail(id){const [d,profiles,emps,del]=await Promise.all([one('testing_private_documents',id),rows('user_profiles'),rows('testing_employers','employer_name',true),db().from('testing_document_deliveries').select('*').eq('source_type','private_document').eq('source_id',id).order('created_at',{ascending:false})]);setTitle(d.title,'Private document management and recipient delivery.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-documents.html">← Documents</a><button class="tm-btn" id="viewFile">View / Download</button></div><div class="tm-two"><div class="tm-card"><div class="tm-card-head"><h2>Document</h2></div><div class="tm-card-body"><div class="tm-kv">${[['Title',d.title],['Category',d.category],['File',d.original_filename],['Type',d.mime_type],['Uploaded',fmt(d.created_at)]].map(([k,v])=>`<div>${esc(k)}</div><div>${esc(v||'—')}</div>`).join('')}</div><p class="tm-pre">${esc(d.description||'')}</p></div></div><div class="tm-card"><div class="tm-card-head"><h2>Send Document</h2></div><div class="tm-card-body"><form id="sendForm" class="tm-form-grid"><div class="tm-field full"><label>Customer Portal User</label><select name="recipient_user_id"><option value="">No portal delivery</option>${profiles.filter(x=>x.email).map(x=>opt(x.id,`${x.display_name||x.email} — ${x.email}`,d.customer_user_id||'')).join('')}</select></div><div class="tm-field"><label>Recipient Name</label><input name="recipient_name"></div><div class="tm-field"><label>Recipient Email</label><input name="recipient_email" type="email"></div><div class="tm-field full"><label>Employer</label><select name="employer_id"><option value="">None</option>${emps.map(x=>opt(x.id,x.employer_name,d.employer_id||'')).join('')}</select></div><div class="full"><button class="tm-btn primary" type="submit">Send to Portal / Email</button></div></form></div></div></div><div class="tm-card"><div class="tm-card-head"><h2>Delivery History</h2></div><div class="tm-card-body">${table(['Recipient','Portal','Email','Sent'],(del.data||[]).map(x=>`<tr><td>${esc(x.recipient_name||x.recipient_email||'—')}</td><td>${badge(x.portal_status)}</td><td>${badge(x.email_status)}</td><td>${fmt(x.created_at)}</td></tr>`))}</div></div>`;$('#viewFile').onclick=async()=>{try{let z=await db().storage.from(d.storage_bucket).createSignedUrl(d.storage_path,300);if(z.error)throw z.error;window.open(z.data.signedUrl,'_blank','noopener')}catch(x){msg(x.message,'error')}};$('#sendForm').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget),delivery={source_type:'private_document',source_id:id,recipient_user_id:p.recipient_user_id||null,employer_id:p.employer_id||null,recipient_name:p.recipient_name||null,recipient_email:p.recipient_email||null,portal_status:p.recipient_user_id?'sent':'not_sent',email_status:p.recipient_email?'queued':'not_sent',portal_sent_at:p.recipient_user_id?new Date().toISOString():null,email_sent_at:p.recipient_email?new Date().toISOString():null};let z=await db().from('testing_document_deliveries').insert(delivery);if(z.error)throw z.error;if(p.recipient_user_id){await db().from('notifications').insert({recipient_user_id:p.recipient_user_id,channel:'in_app',status:'queued',subject:'New screenings4u Document',body:`A private document titled “${d.title}” has been shared with you by screenings4u.`,metadata:{kind:'private_document',document_id:id,logo_url:'https://elpbnytpciqnbexiaebp.supabase.co/storage/v1/object/public/enterprise_branding/logo-screenings4u.png'}})}msg('Document delivery recorded and portal notification queued.');setTimeout(()=>{init().catch(x=>msg(x.message,'error'))},400)}catch(x){msg(x.message,'error')}}}

async function background(){const id=q.get('id');if(id||q.get('new'))return backgroundEdit(id);setTitle('Background Checks','Manage purchased background checks and manually fulfill Checkr screenings until API credentials are available.');const [checks,cat]=await Promise.all([rows('testing_background_checks'),rows('testing_background_check_catalog','sort_order',true)]);const cm=new Map(cat.map(x=>[x.id,x]));$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn primary" href="admin-testing-background-checks.html?new=1">+ Create Background Check</a><a class="tm-btn" href="https://dashboard.checkr.com" target="_blank" rel="noopener">Open Checkr Dashboard</a></div>${metrics([['Checks',checks.length],['Manual Order Required',checks.filter(x=>x.status==='manual_order_required').length],['Pending',checks.filter(x=>['ordered','pending','review'].includes(x.status)).length],['Complete',checks.filter(x=>x.status==='complete').length]])}<div class="tm-card"><div class="tm-card-head"><div><h2>Manual Checkr Catalog</h2><p>Management categories based on Checkr screening types. Actual package availability and permitted use should be confirmed in your Checkr dashboard.</p></div></div><div class="tm-card-body">${table(['Screening','Category','Description'],cat.filter(x=>x.active).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.category)}</td><td>${esc(x.description||'')}</td></tr>`))}</div></div>${table(['Check','Candidate','Screening','Provider Ref','Status','Management'],checks.map(x=>`<tr><td>${esc(x.check_number)}</td><td>${esc(x.candidate_first_name)} ${esc(x.candidate_last_name)}<span class="tm-sub">${esc(x.candidate_email||'')}</span></td><td>${esc(cm.get(x.catalog_id)?.name||x.package_name||'Custom')}</td><td>${esc(x.provider_reference||'—')}</td><td>${badge(x.status)}</td><td><a class="tm-btn small primary" href="admin-testing-background-checks.html?id=${x.id}">Manage</a></td></tr>`))}`}
async function backgroundEdit(id){const [x,cat,emps,orders]=await Promise.all([id?one('testing_background_checks',id):Promise.resolve({}),rows('testing_background_check_catalog','sort_order',true),rows('testing_employers','employer_name',true),rows('orders')]);setTitle(id?`Background Check ${x.check_number}`:'Create Background Check','Manual Checkr fulfillment management.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-background-checks.html">← Background Checks</a><a class="tm-btn" href="https://dashboard.checkr.com" target="_blank" rel="noopener">Open Checkr Dashboard</a></div><div class="tm-card"><div class="tm-card-body"><form id="f" class="tm-form-grid"><div class="tm-field"><label>First Name *</label><input name="candidate_first_name" required value="${esc(x.candidate_first_name||'')}"></div><div class="tm-field"><label>Last Name *</label><input name="candidate_last_name" required value="${esc(x.candidate_last_name||'')}"></div><div class="tm-field"><label>Email</label><input name="candidate_email" type="email" value="${esc(x.candidate_email||'')}"></div><div class="tm-field"><label>Phone</label><input name="candidate_phone" value="${esc(x.candidate_phone||'')}"></div><div class="tm-field full"><label>Checkr Screening</label><select name="catalog_id"><option value="">Custom / package selected in Checkr</option>${cat.filter(c=>c.active).map(c=>opt(c.id,`${c.name} — ${c.category}`,x.catalog_id||'')).join('')}</select></div><div class="tm-field"><label>Employer</label><select name="employer_id"><option value="">None</option>${emps.map(e=>opt(e.id,e.employer_name,x.employer_id||'')).join('')}</select></div><div class="tm-field"><label>Related Order</label><select name="order_id"><option value="">None</option>${orders.map(o=>opt(o.id,`${o.order_number} — ${o.customer_email}`,x.order_id||'')).join('')}</select></div><div class="tm-field"><label>Checkr Provider Reference</label><input name="provider_reference" value="${esc(x.provider_reference||'')}"></div><div class="tm-field"><label>Status</label><select name="status">${['new','manual_order_required','ordered','pending','review','complete','cancelled'].map(s=>opt(s,s,x.status||'manual_order_required')).join('')}</select></div><div class="tm-field full"><label>Notes</label><textarea name="notes">${esc(x.notes||'')}</textarea></div><div class="full"><button class="tm-btn primary" type="submit">Save Background Check</button></div></form></div></div>`;$('#f').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget);if(p.status==='ordered'&&!x.ordered_at)p.ordered_at=new Date().toISOString();if(p.status==='complete'&&!x.completed_at)p.completed_at=new Date().toISOString();let z=id?await db().from('testing_background_checks').update(p).eq('id',id).select().single():await db().from('testing_background_checks').insert(p).select().single();if(z.error)throw z.error;msg('Background check saved.');replaceQuery({id:z.data.id});await background()}catch(y){msg(y.message,'error')}}}

async function proposals(){const id=q.get('id');if(id||q.get('new'))return proposalEdit(id);setTitle('Proposal Builder','Create detailed employer proposals for On-Site Workplace and Mobile Testing, preview them, and send them to the customer portal/email.');const [p,e]=await Promise.all([rows('testing_proposals'),rows('testing_employers','employer_name',true)]),em=new Map(e.map(x=>[x.id,x]));$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn primary" href="admin-testing-proposals.html?new=1">+ New Proposal</a></div>${table(['Proposal','Employer','Title','Valid Until','Total','Status','Management'],p.map(x=>`<tr><td>${esc(x.proposal_number)}</td><td>${esc(em.get(x.employer_id)?.employer_name||x.customer_name||'—')}</td><td>${esc(x.title)}</td><td>${day(x.valid_until)}</td><td>${money(x.total,x.currency)}</td><td>${badge(x.status)}</td><td><a class="tm-btn small primary" href="admin-testing-proposals.html?id=${x.id}">Open Builder</a></td></tr>`))}`}
async function proposalEdit(id){const [p,emps,services]=await Promise.all([id?one('testing_proposals',id):Promise.resolve({}),rows('testing_employers','employer_name',true),rows('services','name',true)]);const items=id?(await db().from('testing_proposal_items').select('*').eq('proposal_id',id).order('created_at')).data||[]:[];const sections=id?(await db().from('testing_proposal_sections').select('*').eq('proposal_id',id).order('sort_order')).data||[]:[];const deliveries=id?(await db().from('testing_proposal_deliveries').select('*').eq('proposal_id',id).order('created_at',{ascending:false})).data||[]:[];setTitle(id?`Proposal ${p.proposal_number}`:'New Proposal','Full proposal builder with structured sections, service pricing, preview, portal delivery, and branded email notification.');const defaultSections=sections.length?sections:[{section_type:'executive_summary',title:'Executive Summary',body_html:''},{section_type:'scope',title:'Scope of Services',body_html:''},{section_type:'schedule',title:'Scheduling & Service Delivery',body_html:''},{section_type:'terms',title:'Terms & Conditions',body_html:''}];$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-proposals.html">← Proposals</a>${id?`<a class="tm-btn" href="admin-testing-proposals.html?id=${id}&preview=1">Preview</a><a class="tm-btn primary" href="admin-testing-proposals.html?id=${id}&send=1">Send Proposal</a>`:''}</div><div class="tm-card"><div class="tm-card-head"><h2>Proposal Details</h2>${id?badge(p.status):''}</div><div class="tm-card-body"><form id="proposalForm" class="tm-form-grid"><div class="tm-field"><label>Employer *</label><select name="employer_id" required><option value="">Choose employer</option>${emps.map(e=>opt(e.id,e.employer_name,p.employer_id||'')).join('')}</select></div><div class="tm-field"><label>Status</label><select name="status">${['draft','sent','viewed','changes_requested','accepted','declined','expired'].map(s=>opt(s,s,p.status||'draft')).join('')}</select></div><div class="tm-field full"><label>Proposal Title *</label><input name="title" required value="${esc(p.title||'Mobile / On-Site Workplace Testing Proposal')}"></div><div class="tm-field"><label>Customer Name</label><input name="customer_name" value="${esc(p.customer_name||'')}"></div><div class="tm-field"><label>Customer Email</label><input name="customer_email" type="email" value="${esc(p.customer_email||'')}"></div><div class="tm-field"><label>Valid Until</label><input name="valid_until" type="date" value="${esc(p.valid_until||'')}"></div><div class="tm-field"><label>Currency</label><input name="currency" value="${esc(p.currency||'USD')}"></div><div class="tm-field full"><label>Introduction</label><textarea name="introduction">${esc(p.introduction||'')}</textarea></div><div class="full"><h3>Proposal Sections</h3><div id="sections">${defaultSections.map(sectionRow).join('')}</div><button class="tm-btn" type="button" id="addSection">+ Add Section</button></div><div class="full"><h3>Pricing / Service Items</h3><div id="items">${(items.length?items:[{description:'',quantity:1,unit_price:0}]).map(itemRow).join('')}</div><button class="tm-btn" type="button" id="addItem">+ Add Line Item</button></div><div class="tm-field"><label>Subtotal</label><input name="subtotal" type="number" step="0.01" value="${esc(p.subtotal||0)}"></div><div class="tm-field"><label>Discount Total</label><input name="discount_total" type="number" step="0.01" value="${esc(p.discount_total||0)}"></div><div class="tm-field"><label>Tax Total</label><input name="tax_total" type="number" step="0.01" value="${esc(p.tax_total||0)}"></div><div class="tm-field"><label>Total</label><input name="total" type="number" step="0.01" value="${esc(p.total||0)}"></div><div class="tm-field full"><label>Terms</label><textarea name="terms">${esc(p.terms||'')}</textarea></div><div class="tm-field full"><label>Internal Notes</label><textarea name="notes">${esc(p.notes||'')}</textarea></div><div class="full"><button class="tm-btn primary" type="submit">Save Proposal</button></div></form></div></div>${q.get('preview')?proposalPreview(p,defaultSections,items,emps):''}${q.get('send')?`<div class="tm-card"><div class="tm-card-head"><h2>Send Proposal</h2></div><div class="tm-card-body"><form id="sendForm" class="tm-form-grid"><div class="tm-field"><label>Portal User ID (optional)</label><input name="recipient_user_id" placeholder="Customer auth user UUID"></div><div class="tm-field"><label>Recipient Email</label><input name="recipient_email" type="email" value="${esc(p.customer_email||'')}"></div><div class="full"><button class="tm-btn primary" type="submit">Push to Portal + Send Branded Email</button></div></form></div></div>`:''}<div class="tm-card"><div class="tm-card-head"><h2>Delivery History</h2></div><div class="tm-card-body">${table(['Recipient','Portal','Email','Sent'],deliveries.map(x=>`<tr><td>${esc(x.recipient_name||x.recipient_email||'—')}</td><td>${badge(x.portal_status)}</td><td>${badge(x.email_status)}</td><td>${fmt(x.created_at)}</td></tr>`))}</div></div>`;bindProposalRows();$('#proposalForm').onsubmit=async e=>{e.preventDefault();try{const f=formObj(e.currentTarget),secs=$$('.tm-proposal-section').map((r,i)=>({section_type:r.querySelector('[name=section_type]').value,title:r.querySelector('[name=section_title]').value,body_html:r.querySelector('[name=section_body]').value,sort_order:i})).filter(x=>x.title),its=$$('.tm-proposal-item').map(r=>({description:r.querySelector('[name=item_desc]').value,quantity:Number(r.querySelector('[name=item_qty]').value||1),unit_price:Number(r.querySelector('[name=item_price]').value||0),discount_amount:0,tax_rate:0})).filter(x=>x.description);let z;if(id)z=await db().from('testing_proposals').update(f).eq('id',id).select().single();else z=await db().from('testing_proposals').insert({...f,id:crypto.randomUUID(),proposal_number:'PR-'+crypto.randomUUID().slice(0,8).toUpperCase()}).select().single();if(z.error)throw z.error;await db().from('testing_proposal_sections').delete().eq('proposal_id',z.data.id);if(secs.length){let a=await db().from('testing_proposal_sections').insert(secs.map(x=>({...x,proposal_id:z.data.id})));if(a.error)throw a.error}await db().from('testing_proposal_items').delete().eq('proposal_id',z.data.id);if(its.length){let a=await db().from('testing_proposal_items').insert(its.map(x=>({...x,id:crypto.randomUUID(),proposal_id:z.data.id,line_total:x.quantity*x.unit_price,tax_amount:0})));if(a.error)throw a.error}msg('Proposal saved.');replaceQuery({id:z.data.id});await proposals()}catch(x){msg(x.message,'error')}};if($('#sendForm'))$('#sendForm').onsubmit=async e=>{e.preventDefault();try{const a=formObj(e.currentTarget);await rpc('testing_send_proposal',{p_proposal_id:id,p_recipient_user_id:a.recipient_user_id||null,p_recipient_email:a.recipient_email||null});msg('Proposal pushed and branded notification queued.');await proposalEdit(id)}catch(x){msg(x.message,'error')}}}
function sectionRow(s={}){return `<div class="tm-proposal-section"><div class="tm-field"><label>Section Type</label><select name="section_type">${['cover','executive_summary','scope','services','schedule','pricing','terms','about','custom'].map(x=>opt(x,x,s.section_type||'custom')).join('')}</select></div><div><div class="tm-field"><label>Section Title</label><input name="section_title" value="${esc(s.title||'')}"></div><div class="tm-field"><label>Content</label><textarea name="section_body">${esc(s.body_html||'')}</textarea></div></div><button class="tm-btn danger small" type="button" data-remove-section>Remove</button></div>`}
function itemRow(i={}){return `<div class="tm-proposal-item"><div class="tm-field"><label>Description</label><input name="item_desc" value="${esc(i.description||'')}"></div><div class="tm-field"><label>Qty</label><input name="item_qty" type="number" step="0.01" value="${esc(i.quantity||1)}"></div><div class="tm-field"><label>Unit Price</label><input name="item_price" type="number" step="0.01" value="${esc(i.unit_price||0)}"></div><button class="tm-btn danger small" type="button" data-remove-item>Remove</button></div>`}
function bindProposalRows(){const bind=()=>{$$('[data-remove-section]').forEach(b=>b.onclick=()=>b.closest('.tm-proposal-section').remove());$$('[data-remove-item]').forEach(b=>b.onclick=()=>b.closest('.tm-proposal-item').remove())};bind();$('#addSection').onclick=()=>{$('#sections').insertAdjacentHTML('beforeend',sectionRow({title:'New Section'}));bind()};$('#addItem').onclick=()=>{$('#items').insertAdjacentHTML('beforeend',itemRow({quantity:1,unit_price:0}));bind()}}
function proposalPreview(p,secs,items,emps){const em=emps.find(x=>x.id===p.employer_id);return `<div class="tm-card"><div class="tm-card-head"><h2>Proposal Preview</h2></div><div class="tm-card-body"><div class="tm-preview"><img class="tm-logo-email" src="https://elpbnytpciqnbexiaebp.supabase.co/storage/v1/object/public/enterprise_branding/logo-screenings4u.png"><h1>${esc(p.title||'Proposal')}</h1><p><strong>Prepared for:</strong> ${esc(em?.employer_name||p.customer_name||'Employer')}</p>${p.introduction?`<p>${esc(p.introduction)}</p>`:''}${secs.map(s=>`<h2>${esc(s.title)}</h2><div>${s.body_html||''}</div>`).join('')}${items.length?table(['Service','Qty','Unit Price'],items.map(i=>`<tr><td>${esc(i.description)}</td><td>${esc(i.quantity)}</td><td>${money(i.unit_price,p.currency)}</td></tr>`)):''}<h2>Total: ${money(p.total,p.currency)}</h2><h2>Terms</h2><p class="tm-pre">${esc(p.terms||'')}</p></div></div></div>`}

async function blog(){const id=q.get('id');if(id||q.get('new'))return blogEdit(id);setTitle('screenings4u Blog Editor','This management page uses screenings4u_blog only. Training, Workforce, and DOT blog tables exist for future business-unit tabs.');const posts=await rows('screenings4u_blog');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn primary" href="admin-testing-blog.html?new=1">+ New Blog Post</a></div>${table(['Title','Slug','SEO Title','Status','Published','Management'],posts.map(x=>`<tr><td><strong>${esc(x.title)}</strong><span class="tm-sub">${esc(x.excerpt||'')}</span></td><td>${esc(x.slug)}</td><td>${esc(x.seo_title||'—')}</td><td>${badge(x.status)}</td><td>${fmt(x.published_at)}</td><td><a class="tm-btn small primary" href="admin-testing-blog.html?id=${x.id}">Edit</a></td></tr>`))}`}
async function blogEdit(id){const p=id?await one('screenings4u_blog',id):{};setTitle(id?`Edit Blog — ${p.title}`:'New screenings4u Blog Post','Rich text, image upload, SEO, inline preview, draft/publish workflow.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-blog.html">← Blog Posts</a>${id?`<a class="tm-btn" href="admin-testing-blog.html?id=${id}&preview=1">Preview</a>`:''}</div><div class="tm-card"><div class="tm-card-body"><form id="blogForm" class="tm-form-grid"><div class="tm-field full"><label>Title *</label><input name="title" id="blogTitle" required value="${esc(p.title||'')}"></div><div class="tm-field"><label>Slug *</label><input name="slug" id="blogSlug" required value="${esc(p.slug||'')}"></div><div class="tm-field"><label>Status</label><select name="status">${['draft','published','archived'].map(x=>opt(x,x,p.status||'draft')).join('')}</select></div><div class="tm-field full"><label>Excerpt</label><textarea name="excerpt">${esc(p.excerpt||'')}</textarea></div><div class="full"><label style="font-size:10px;font-weight:800;text-transform:uppercase;color:#536887">Blog Content</label><div class="tm-editor-toolbar"><select id="fontFamily"><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Times New Roman">Times New Roman</option><option value="Verdana">Verdana</option></select><select id="formatBlock"><option value="p">Paragraph</option><option value="h2">Heading 2</option><option value="h3">Heading 3</option><option value="blockquote">Quote</option></select><button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><button type="button" data-cmd="underline"><u>U</u></button><button type="button" data-cmd="insertUnorderedList">• Bullets</button><button type="button" data-cmd="insertOrderedList">1. Numbers</button><input id="linkUrl" placeholder="https:// link"><button type="button" id="applyLink">Add Link</button></div><div id="editor" class="tm-editor" contenteditable="true">${p.content_html||''}</div></div><div class="tm-field"><label>Featured Image URL</label><input name="featured_image_url" id="featuredUrl" value="${esc(p.featured_image_url||'')}"></div><div class="tm-field"><label>Featured Image Alt Text</label><input name="featured_image_alt" value="${esc(p.featured_image_alt||'')}"></div><div class="tm-field full"><label>Upload Featured / Content Image</label><input id="blogImage" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><button class="tm-btn" id="uploadImage" type="button">Upload Image</button></div><div class="tm-field"><label>SEO Title</label><input name="seo_title" value="${esc(p.seo_title||'')}"></div><div class="tm-field"><label>SEO Keywords</label><input name="seo_keywords" value="${esc((p.seo_keywords||[]).join(', '))}"></div><div class="tm-field full"><label>SEO Meta Description</label><textarea name="seo_description">${esc(p.seo_description||'')}</textarea></div><div class="tm-field full"><label>Canonical URL</label><input name="canonical_url" value="${esc(p.canonical_url||'')}"></div><div class="tm-field"><label>Author Name</label><input name="author_name" value="${esc(p.author_name||'screenings4u Editorial Team')}"></div><div class="tm-actions full"><button class="tm-btn primary" type="submit">Save Blog Post</button>${id?`<a class="tm-btn danger" href="admin-testing-blog.html?id=${id}&delete=1">Delete</a>`:''}</div></form></div></div>${q.get('preview')?`<div class="tm-card"><div class="tm-card-head"><h2>Blog Preview</h2></div><div class="tm-card-body"><article class="tm-preview">${p.featured_image_url?`<img src="${esc(p.featured_image_url)}" alt="${esc(p.featured_image_alt||'')}">`:''}<h1>${esc(p.title||'')}</h1><p>${esc(p.excerpt||'')}</p>${p.content_html||''}</article></div></div>`:''}${q.get('delete')?`<div class="tm-danger-zone"><h3>Delete this blog post?</h3><form id="deleteBlog"><button class="tm-btn danger" type="submit">Confirm Delete</button> <a class="tm-btn" href="admin-testing-blog.html?id=${id}">Cancel</a></form></div>`:''}`;$$('[data-cmd]').forEach(b=>b.onclick=()=>{document.execCommand(b.dataset.cmd,false);$('#editor').focus()});$('#fontFamily').onchange=e=>document.execCommand('fontName',false,e.target.value);$('#formatBlock').onchange=e=>document.execCommand('formatBlock',false,e.target.value);$('#applyLink').onclick=()=>{const u=$('#linkUrl').value.trim();if(/^https:\/\//i.test(u))document.execCommand('createLink',false,u);else msg('Enter an HTTPS link first.','warn')};if(!id)$('#blogTitle').oninput=()=>{if(!$('#blogSlug').value)$('#blogSlug').value=$('#blogTitle').value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')};$('#uploadImage').onclick=async()=>{try{const f=$('#blogImage').files[0];if(!f)throw new Error('Choose an image first.');const path=`blog/${new Date().getFullYear()}/${crypto.randomUUID()}-${f.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;let up=await db().storage.from('testing-blog-images').upload(path,f,{contentType:f.type});if(up.error)throw up.error;const url=db().storage.from('testing-blog-images').getPublicUrl(path).data.publicUrl;$('#featuredUrl').value=url;document.execCommand('insertImage',false,url);msg('Image uploaded and inserted.')}catch(x){msg(x.message,'error')}};$('#blogForm').onsubmit=async e=>{e.preventDefault();try{const a=formObj(e.currentTarget);a.content_html=$('#editor').innerHTML;a.seo_keywords=a.seo_keywords.split(',').map(x=>x.trim()).filter(Boolean);a.published_at=a.status==='published'?(p.published_at||new Date().toISOString()):null;let z=id?await db().from('screenings4u_blog').update(a).eq('id',id).select().single():await db().from('screenings4u_blog').insert(a).select().single();if(z.error)throw z.error;msg(a.status==='published'?'Blog post published.':'Blog post saved.');replaceQuery({id:z.data.id});await blog()}catch(x){msg(x.message,'error')}};if($('#deleteBlog'))$('#deleteBlog').onsubmit=async e=>{e.preventDefault();try{let z=await db().from('screenings4u_blog').delete().eq('id',id);if(z.error)throw z.error;replaceQuery();await blog()}catch(x){msg(x.message,'error')}}}

async function people(){setTitle('Employers & Testing Customers','All employer accounts plus customers who purchased screenings4u testing services.');const [emps,orders,profiles]=await Promise.all([rows('testing_employers','employer_name',true),rows('orders'),rows('user_profiles')]);const testOrders=orders.filter(o=>o.fulfillment_type==='testing'||o.metadata?.finance_business_code==='testing'),customerKeys=new Map();for(const o of testOrders){const k=o.user_id||String(o.customer_email||'').toLowerCase();if(!k)continue;const x=customerKeys.get(k)||{user_id:o.user_id,email:o.customer_email,name:[o.customer_first_name,o.customer_last_name].filter(Boolean).join(' '),orders:0,last:null,company:o.company_name};x.orders++;if(!x.last||o.created_at>x.last)x.last=o.created_at;customerKeys.set(k,x)}$('#tmRoot').innerHTML=`<div class="tm-card"><div class="tm-card-head"><h2>Employers</h2></div><div class="tm-card-body">${table(['Employer','Contact','Location','Employees','Status'],emps.map(e=>`<tr><td><strong>${esc(e.employer_name)}</strong><span class="tm-sub">${esc(e.legal_name||'')}</span></td><td>${esc(e.email||'—')}<span class="tm-sub">${esc(e.phone||'')}</span></td><td>${esc([e.city,e.state,e.postal_code].filter(Boolean).join(', '))}</td><td>${esc(e.employee_count??'—')}</td><td>${badge(e.status)}</td></tr>`))}</div></div><div class="tm-card"><div class="tm-card-head"><h2>Customers Who Purchased Testing Services</h2></div><div class="tm-card-body">${table(['Customer','Company','Testing Orders','Last Purchase','Portal'],[...customerKeys.values()].map(c=>`<tr><td><strong>${esc(c.name||c.email||'Customer')}</strong><span class="tm-sub">${esc(c.email||'')}</span></td><td>${esc(c.company||'—')}</td><td>${c.orders}</td><td>${fmt(c.last)}</td><td>${c.user_id?`<a class="tm-btn small" href="admin-testing-portal-access.html?user_id=${c.user_id}">Manage Access</a>`:'No linked portal user'}</td></tr>`))}</div></div>`}

async function portalAccess(){setTitle('Portal Access','Grant, suspend, and revoke screenings4u customer portal access.');const [access,profiles]=await Promise.all([rows('testing_customer_portal_access'),rows('user_profiles')]);const am=new Map(access.map(x=>[x.user_id,x]));const uid=q.get('user_id');if(uid){const p=profiles.find(x=>x.id===uid)||{},a=am.get(uid)||{};$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-portal-access.html">← Portal Access</a></div><div class="tm-card"><div class="tm-card-head"><h2>${esc(p.display_name||p.email||'Portal User')}</h2>${badge(a.status||'revoked')}</div><div class="tm-card-body"><form id="accessForm" class="tm-form-grid"><div class="tm-field full"><label>Email</label><input value="${esc(p.email||'')}" disabled></div><div class="tm-field"><label>Portal Access</label><select name="status">${['active','suspended','revoked'].map(x=>opt(x,x,a.status||'revoked')).join('')}</select></div><div class="full"><button class="tm-btn primary" type="submit">Save Access</button></div></form></div></div>`;$('#accessForm').onsubmit=async e=>{e.preventDefault();try{const st=formObj(e.currentTarget).status,existing=am.get(uid);let z=existing?await db().from('testing_customer_portal_access').update({status:st,suspended_at:st==='suspended'?new Date().toISOString():null,revoked_at:st==='revoked'?new Date().toISOString():null}).eq('id',existing.id):await db().from('testing_customer_portal_access').insert({user_id:uid,status:st,access_source:'admin',first_enabled_at:new Date().toISOString()});if(z.error)throw z.error;msg('Portal access updated.');setTimeout(()=>{init().catch(x=>msg(x.message,'error'))},350)}catch(x){msg(x.message,'error')}};return}const visible=profiles.filter(p=>p.email);$('#tmRoot').innerHTML=table(['User','Status','First Enabled','Suspended','Revoked','Management'],visible.map(p=>{const a=am.get(p.id)||{};return `<tr><td><strong>${esc(p.display_name||[p.first_name,p.last_name].filter(Boolean).join(' ')||'Customer')}</strong><span class="tm-sub">${esc(p.email)}</span></td><td>${badge(a.status||'revoked')}</td><td>${fmt(a.first_enabled_at)}</td><td>${fmt(a.suspended_at)}</td><td>${fmt(a.revoked_at)}</td><td><a class="tm-btn small primary" href="admin-testing-portal-access.html?user_id=${p.id}">Manage</a></td></tr>`}))}

async function providers(){setTitle('Testing Providers','Manage collection sites, laboratories, and MRO providers.');const type=q.get('type'),id=q.get('id');if(type&&(id||q.get('new')))return providerEdit(type,id);const d=await legacy('providers');const sec=(title,t,a)=>`<div class="tm-card"><div class="tm-card-head"><div><h2>${title}</h2><p>${a.length} provider(s)</p></div><a class="tm-btn primary small" href="admin-testing-providers.html?type=${t}&new=1">+ Add</a></div><div class="tm-card-body">${table(['Provider','Status','Location / Contact','Management'],a.map(x=>`<tr><td><strong>${esc(x.name)}</strong><span class="tm-sub">${esc(x.site_code||x.external_code||x.license_number||'')}</span></td><td>${badge(x.status)}</td><td>${esc(x.city?[x.city,x.state].filter(Boolean).join(', '):x.contact?.email||'—')}</td><td><a class="tm-btn small" href="admin-testing-providers.html?type=${t}&id=${x.id}">Manage</a></td></tr>`))}</div></div>`;$('#tmRoot').innerHTML=sec('Collection Sites','collection_site',d.collection_sites||[])+sec('Laboratories','laboratory',d.laboratories||[])+sec('MROs','mro',d.mros||[])}
async function providerEdit(type,id){const d=await legacy('providers'),map={collection_site:d.collection_sites||[],laboratory:d.laboratories||[],mro:d.mros||[]},x=map[type].find(v=>v.id===id)||{};setTitle(`${id?'Manage':'Add'} ${type.replace('_',' ')}`,'Testing provider record.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-providers.html">← Providers</a></div><div class="tm-card"><div class="tm-card-body"><form id="pf" class="tm-form-grid"><div class="tm-field full"><label>Name *</label><input name="name" required value="${esc(x.name||'')}"></div><div class="tm-field"><label>Status</label><select name="status">${['active','inactive','archived'].map(s=>opt(s,s,x.status||'active')).join('')}</select></div>${type==='collection_site'?`<div class="tm-field"><label>Site Code</label><input name="site_code" value="${esc(x.site_code||'')}"></div><div class="tm-field"><label>Email</label><input name="email" value="${esc(x.email||'')}"></div><div class="tm-field"><label>Phone</label><input name="phone" value="${esc(x.phone||'')}"></div><div class="tm-field full"><label>Address</label><input name="address_line_1" value="${esc(x.address_line_1||'')}"></div><div class="tm-field"><label>City</label><input name="city" value="${esc(x.city||'')}"></div><div class="tm-field"><label>State</label><input name="state" value="${esc(x.state||'')}"></div><div class="tm-field"><label>ZIP</label><input name="postal_code" value="${esc(x.postal_code||'')}"></div>`:type==='laboratory'?`<div class="tm-field"><label>External Code</label><input name="external_code" value="${esc(x.external_code||'')}"></div>`:`<div class="tm-field"><label>License Number</label><input name="license_number" value="${esc(x.license_number||'')}"></div><div class="tm-field"><label>Contact Email</label><input name="email" value="${esc(x.contact?.email||'')}"></div>`}<div class="full"><button class="tm-btn primary" type="submit">Save Provider</button></div></form></div></div>`;$('#pf').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget);if(id){p.id=id;p.expected_updated_at=x.updated_at}await legacyAct(type==='collection_site'?'save_collection_site':type==='laboratory'?'save_laboratory':'save_mro',p);msg('Provider saved.');replaceQuery();await providers()}catch(y){msg(y.message,'error')}}}

async function catalog(){const id=q.get('id');if(id||q.get('new'))return catalogEdit(id);setTitle('Testing Catalog','Manage screenings4u testing services and storefront pricing.');const d=await legacy('services'),a=(d.services||[]).filter(testingService);$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn primary" href="admin-testing-catalog.html?new=1">+ Add Testing Service</a></div>${table(['Service','SKU','Category','Price','Order Type','Status','Management'],a.map(s=>`<tr><td><strong>${esc(s.name)}</strong><span class="tm-sub">${esc(s.description||'')}</span></td><td>${esc(s.sku||'—')}</td><td>${esc(s.metadata?.category||'—')}</td><td>${s.current_price?money(s.current_price.amount,s.current_price.currency):'—'}</td><td>${esc(s.metadata?.order_type||'—')}</td><td>${badge(s.active!==false?'active':'inactive')}</td><td><a class="tm-btn small primary" href="admin-testing-catalog.html?id=${s.id}">Manage</a></td></tr>`))}`}
async function catalogEdit(id){const d=await legacy('services'),s=(d.services||[]).find(x=>x.id===id)||{};setTitle(id?`Manage Service — ${s.name}`:'Add Testing Service','Testing catalog, price, order URL, and storefront metadata.');$('#tmRoot').innerHTML=`<div class="tm-page-actions"><a class="tm-btn" href="admin-testing-catalog.html">← Catalog</a></div><div class="tm-card"><div class="tm-card-body"><form id="sf" class="tm-form-grid"><div class="tm-field full"><label>Name *</label><input name="name" required value="${esc(s.name||'')}"></div><div class="tm-field"><label>SKU *</label><input name="sku" required value="${esc(s.sku||'')}"></div><div class="tm-field"><label>Slug *</label><input name="slug" required value="${esc(s.slug||'')}"></div><div class="tm-field full"><label>Description</label><textarea name="description">${esc(s.description||'')}</textarea></div><div class="tm-field"><label>Category</label><input name="category" value="${esc(s.metadata?.category||'')}"></div><div class="tm-field"><label>Specimen</label><input name="specimen" value="${esc(s.metadata?.specimen||'')}"></div><div class="tm-field"><label>Testing Scope</label><select name="testing_scope">${opt('non_dot','Non-DOT',s.metadata?.testing_scope||'non_dot')+opt('dot','DOT',s.metadata?.testing_scope||'non_dot')}</select></div><div class="tm-field"><label>Order Type</label><select name="order_type">${['checkout','contact','custom_form'].map(x=>opt(x,x,s.metadata?.order_type||'checkout')).join('')}</select></div><div class="tm-field"><label>Price</label><input name="price" type="number" step="0.01" value="${esc(s.current_price?.amount||0)}"></div><div class="tm-field"><label>Currency</label><input name="currency" value="${esc(s.current_price?.currency||'USD')}"></div><div class="tm-field full"><label>Order URL</label><input name="order_url" value="${esc(s.metadata?.order_url||'')}"></div><div class="tm-field"><label>Active</label><select name="active">${opt('true','Yes',String(s.active!==false))+opt('false','No',String(s.active!==false))}</select></div><div class="full"><button class="tm-btn primary" type="submit">Save Service</button></div></form></div></div>`;$('#sf').onsubmit=async e=>{e.preventDefault();try{const p=formObj(e.currentTarget);p.active=p.active==='true';if(id){p.id=id;p.expected_updated_at=s.updated_at}await legacyAct('save_service',p);msg('Service saved.');replaceQuery();await catalog()}catch(x){msg(x.message,'error')}}}

async function reports(){setTitle('Testing Reports','Operational reporting across testing management. Revenue is intentionally excluded and belongs in Finance.');const [w,r,c,b,col,p,d]=await Promise.all([rows('testing_work_orders'),rows('testing_employer_service_requests'),rows('testing_cases'),rows('testing_background_checks'),rows('collector_network_submissions'),rows('testing_proposals'),rows('testing_document_deliveries')]);const byStatus={};c.forEach(x=>byStatus[x.status]=(byStatus[x.status]||0)+1);const byType={};w.forEach(x=>byType[x.work_order_type]=(byType[x.work_order_type]||0)+1);$('#tmRoot').innerHTML=metrics([['Testing Cases',c.length],['Completed / Released',c.filter(x=>['released','completed'].includes(x.status)).length],['Work Orders',w.length],['Service Requests',r.length]])+`<div class="tm-three"><div class="tm-card"><div class="tm-card-head"><h2>Case Status</h2></div><div class="tm-card-body">${table(['Status','Count'],Object.entries(byStatus).map(([k,v])=>`<tr><td>${badge(k)}</td><td>${v}</td></tr>`))}</div></div><div class="tm-card"><div class="tm-card-head"><h2>Work Order Types</h2></div><div class="tm-card-body">${table(['Type','Count'],Object.entries(byType).map(([k,v])=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${v}</td></tr>`))}</div></div><div class="tm-card"><div class="tm-card-head"><h2>Network & Records</h2></div><div class="tm-card-body"><div class="tm-kv"><div>Collectors</div><div>${col.length}</div><div>Approved</div><div>${col.filter(x=>x.status==='approved').length}</div><div>Background Checks</div><div>${b.length}</div><div>Proposals</div><div>${p.length}</div><div>Document Deliveries</div><div>${d.length}</div></div></div></div></div><div class="tm-card"><div class="tm-card-head"><h2>Exports</h2></div><div class="tm-card-body tm-actions"><button class="tm-btn" data-export="cases">Cases CSV</button><button class="tm-btn" data-export="workorders">Work Orders CSV</button><button class="tm-btn" data-export="requests">Requests CSV</button><button class="tm-btn" data-export="collectors">Collectors CSV</button><button class="tm-btn" data-export="background">Background Checks CSV</button></div></div>`;const data={cases:c,workorders:w,requests:r,collectors:col,background:b};$$('[data-export]').forEach(b=>b.onclick=()=>downloadCsv(`${b.dataset.export}.csv`,data[b.dataset.export]))}
function downloadCsv(name,a){if(!a.length)return msg('No records to export.','warn');const keys=[...new Set(a.flatMap(x=>Object.keys(x).filter(k=>typeof x[k]!=='object')))],csv=[keys.join(','),...a.map(x=>keys.map(k=>`"${String(x[k]??'').replaceAll('"','""')}"`).join(','))].join('\n'),el=document.createElement('a');el.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));el.download=name;el.click();setTimeout(()=>URL.revokeObjectURL(el.href),1000)}

async function init(){installNav();const page=document.body.dataset.testingPage||'home';const routes={home,collectors,work_orders:workOrders,mobile:()=>requestPage('mobile'),post_accident:()=>requestPage('post_accident'),operations,results,result_documents:resultDocuments,documents,background,proposals,blog,people,portal_access:portalAccess,providers,catalog,reports};try{await (routes[page]||home)();unlock()}catch(e){console.error(e);$('#tmRoot').innerHTML=`<div class="tm-message error"><strong>Unable to load page.</strong><br>${esc(e.message||e)}</div>`;unlock()}}
window.S4UTestingRefresh=()=>init();document.addEventListener('s4u:testing-refresh',()=>init());document.addEventListener('DOMContentLoaded',()=>setTimeout(init,0));
})();
